  () => {
    const p = window.__CHAR__?.pos;
    const s = (window as unknown as { __settle?: { x: number | null; t: number } })
      .__settle;
    if (!p || !s) return null;
    const now = Date.now();
    if (s.x === null || Math.hypot(p.x - s.x, p.z - s.z) > 0.06) {
      s.x = p.x;
      s.t = now;
      return null;
    }
    return now - s.t >= 600 ? true : null;
  },
  null,
  { timeout: 15_000, polling: 100 },
);

